CREATE COLUMN TABLE "TEST_AP"."ODDG" ("Numerator" INTEGER CS_INT NOT NULL , "DdgCode" NVARCHAR(2) NOT NULL , "DdgName" NVARCHAR(30) NOT NULL , "DdctPrcnt" DECIMAL(21,6) CS_FIXED, "DataSource" NVARCHAR(1) DEFAULT 'N', "UserSign" SMALLINT CS_INT, PRIMARY KEY ("Numerator")) UNLOAD PRIORITY 5  AUTO MERGE ;
CREATE UNIQUE INDEX "ODDG_NAME" ON "TEST_AP"."ODDG" ( "DdgCode" ASC, "DdgName" ASC )